function publish(){captureDraft();if(!draft.title.trim()||!draft.text.trim())return toast('请填写标题和记录内容');if(!draft.date)return toast('请选择记忆时间');draft.images=draft.images||[];if(draft.id)memories=memories.map(m=>m.id===draft.id?draft:m);else{draft.id=Date.now();memories.unshift(draft)}save();go('瞬间');toast('瞬间已保存，时光集已更新')}
const defaultProfile = { nickname:'Calmer', account:'calmer', signature:'把日子留给自己', avatar:'', background:'' };
let userProfile = {...defaultProfile};
try {
  userProfile = {...defaultProfile, ...JSON.parse(localStorage.getItem('you-profile'))};
} catch {}

function saveProfile(changes) {
  const next = {...userProfile, ...changes};
  try {
    localStorage.setItem('you-profile', JSON.stringify(next));
  } catch {
    toast('资料保存失败，请检查浏览器存储空间');
    return false;
  }
  userProfile = next;
  return true;
}

function profile(view = 'card') {
  const {nickname, account, signature, background} = userProfile;
  const cover = esc(background || imgs[1]);
  const editing = view !== 'card';
  const avatarButton = `
    <button class="profile-avatar" type="button" aria-label="更换头像" onclick="this.closest('.sheet').querySelector('[data-avatar]').click()">
      <img src="${esc(userProfile.avatar || avatar)}" alt=""><span>${icon('image')}</span>
    </button>`;
  const pickBackground = "this.closest('.sheet').querySelector('[data-background]').click()";
  let content;
  if (view === 'card') {
    content = `
      <img class="profile-background" src="${cover}" alt="">
      <div class="profile-identity">
        ${avatarButton}
        <div class="profile-name"><h2>${esc(nickname)}</h2><p>you ID：${esc(account)}</p></div>
        <div class="profile-toolbar">
          <button type="button" onclick="profile('list')" aria-label="编辑资料">${icon('edit')}</button>
          <button type="button" onclick="${pickBackground}" aria-label="更换背景">${icon('image')}</button>
        </div>
      </div>
      <div class="profile-stats">
        <span><strong>${memories.filter(isMine).length}</strong> 瞬间</span>
        <span><strong>${trips.length}</strong> 同行</span>
        <span><strong>${circles.length}</strong> 圈子</span>
      </div>
      <p class="profile-signature">${esc(signature || '还没有个性签名')}</p>`;
  } else if (view === 'list') {
    content = `
      <div class="profile-nav">
        <button type="button" onclick="profile()" aria-label="返回资料卡">${icon('back')}</button>
        <h2>编辑资料</h2>
        <button type="button" onclick="profile()">预览</button>
      </div>
      <div class="profile-editor-avatar">${avatarButton}</div>
      <div class="profile-group">
        <button class="profile-row" type="button" onclick="profile('nickname')"><span>昵称</span><span>${esc(nickname)}</span>${icon('arrow')}</button>
        <div class="profile-row"><span>you ID</span><span>${esc(account)}</span></div>
        <button class="profile-row" type="button" onclick="${pickBackground}"><span>背景</span><img class="profile-thumbnail" src="${cover}" alt="当前背景">${icon('arrow')}</button>
      </div>
      <div class="profile-group">
        <button class="profile-row" type="button" onclick="profile('signature')"><span>个性签名</span><span>${esc(signature || '添加签名')}</span>${icon('arrow')}</button>
      </div>`;
  } else {
    const bio = view === 'signature';
    const limit = bio ? 160 : 24;
    const value = bio ? signature : nickname;
    const count = "this.form.querySelector('output').textContent=this.value.length+'/" + limit + "'";
    content = `
      <form class="profile-form" onsubmit="submitProfile(event,'${view}')">
        <div class="profile-nav">
          <button type="button" onclick="profile('list')" aria-label="返回编辑资料">${icon('back')}</button>
          <h2>${bio ? '编辑个性签名' : '编辑昵称'}</h2>
          <button type="submit">保存</button>
        </div>
        <div class="profile-field">
          ${bio ? `<textarea name="value" aria-label="个性签名" maxlength="${limit}" rows="5" oninput="${count}">\n${esc(value)}</textarea>` :
            `<input name="value" aria-label="昵称" value="${esc(value)}" maxlength="${limit}" oninput="${count}" required>`}
          <output>${value.length}/${limit}</output>
        </div>
      </form>`;
  }

  sheet(`
    <div class="profile-content">${content}</div>
    <input type="file" hidden data-avatar accept="image/*" onchange="changeProfileImage(this,'avatar')">
    <input type="file" hidden data-background accept="image/*" onchange="changeProfileImage(this,'background')">
  `, {showClose:false, profileCard:true, editing});
  enableProfileDrag($('#overlay .sheet'));
}

function submitProfile(event, field) {
  event.preventDefault();
  if (field !== 'nickname' && field !== 'signature') return;
  const value = event.currentTarget.elements.value.value.trim();
  if (field === 'nickname' && !value) {
    toast('请填写昵称');
    return;
  }
  if (saveProfile({[field]:value})) profile('list');
}

async function changeProfileImage(input, field) {
  const file = input.files[0];
  if (!file) return;
  input.value = '';
  try {
    const bitmap = await createImageBitmap(file);
    const maxSize = field === 'avatar' ? 384 : 1200;
    const scale = Math.min(1, maxSize / Math.max(bitmap.width, bitmap.height));
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(bitmap.width * scale));
    canvas.height = Math.max(1, Math.round(bitmap.height * scale));
    canvas.getContext('2d').drawImage(bitmap, 0, 0, canvas.width, canvas.height);
    bitmap.close();
    if (!input.isConnected || input.closest('.shade').classList.contains('profile-leaving')) return;
    const source = canvas.toDataURL('image/webp', .84);
    if (!saveProfile({[field]:source})) return;
    if (field === 'background') {
      input.closest('.sheet').querySelector('.profile-background, .profile-thumbnail').src = source;
    } else {
      input.closest('.sheet').querySelector('.profile-avatar img').src = source;
      document.querySelectorAll('.header button[onclick="profile()"] img').forEach(img => { img.src = source; });
    }
  } catch {
    if (input.isConnected) toast('无法读取这张图片，请试试其他图片');
  }
}

function enableProfileDrag(card) {
  const shade = card.parentElement;
  let drag;
  card.addEventListener('pointerdown', event => {
    if (!event.isPrimary || event.button !== 0 || shade.classList.contains('profile-leaving')) return;
    if (event.target.closest('button,input,textarea,label') ||
        (card.classList.contains('profile-editing') && !event.target.closest('.profile-grip'))) return;
    drag = {id:event.pointerId, start:event.clientY, offset:0};
    card.setPointerCapture(event.pointerId);
    card.classList.add('profile-dragging');
  });
  card.addEventListener('pointermove', event => {
    if (drag?.id !== event.pointerId) return;
    drag.offset = Math.max(0, event.clientY - drag.start);
    card.style.setProperty('--profile-offset', `${drag.offset}px`);
  });
  function finish(event) {
    if (drag?.id !== event.pointerId) return;
    const dismiss = event.type === 'pointerup' && drag.offset >= Math.min(96, card.offsetHeight / 3);
    drag = null;
    card.classList.remove('profile-dragging');
    if (dismiss) closeSheet();
    else card.style.removeProperty('--profile-offset');
  }
  for (const type of ['pointerup','pointercancel','lostpointercapture']) card.addEventListener(type, finish);
}
// Interaction and visual refinements.
const moodStyles={开心:['#936222','#ffe6aa','happy'],平静:['#466b82','#d9edf9','smile'],松弛:['#527348','#e1efd6','sleeping'],心动:['#a05371','#f9dce9','heart'],惊喜:['#8c659a','#edddf8','sparkles'],自在:['#3c7971','#d3efea','smile'],低落:['#65728d','#e1e6f3','sad-01']};
function moodBadge(mood,label=mood){let [ink,bg,glyph]=moodStyles[mood]||moodStyles.平静;return `<span class="emotion" style="--emotion-ink:${ink};--emotion-bg:${bg}cc" aria-label="${esc(mood)}" title="${esc(mood)}">${icon(glyph)}${label}</span>`}
function tagBadge(tag){return `<span class="tag-decor">${icon('sparkles')}<span>${esc(tag)}</span></span>`}
function gallery(m,kind='moment'){return `<div class="gallery ${kind}" data-gallery><div class="gallery-track" tabindex="0" aria-label="${esc(m.title)}，左右滑动浏览组图" onscroll="galleryProgress(this)" onkeydown="galleryKey(event,this)">${m.images.map((src,i)=>`<div class="gallery-slide"><img draggable="false" src="${src}" alt="${esc(m.title)} · 第 ${i+1} 张" ${i?'loading="lazy"':''}></div>`).join('')}</div>${m.images.length>1?`<span class="gallery-count">1/${m.images.length}</span><div class="gallery-dots" aria-hidden="true">${m.images.map((_,i)=>`<i class="${i===0?'selected':''}"></i>`).join('')}</div>`:''}</div>`}
function galleryProgress(track){let index=Math.round(track.scrollLeft/track.clientWidth),root=track.parentElement;let count=root.querySelector('.gallery-count');if(count)count.textContent=`${index+1}/${track.children.length}`;root.querySelectorAll('.gallery-dots i').forEach((dot,i)=>dot.classList.toggle('selected',i===index))}
function galleryKey(event,track){if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();track.scrollBy({left:track.clientWidth*(event.key==='ArrowRight'?1:-1),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}}
let dragGallery=null;
document.addEventListener('pointerdown',event=>{let track=event.target.closest('.gallery-track');if(!track||event.pointerType!=='mouse')return;dragGallery={track,x:event.clientX,y:event.clientY,left:track.scrollLeft,dragged:false};track.setPointerCapture(event.pointerId)});
document.addEventListener('pointermove',event=>{if(!dragGallery)return;let d=dragGallery,dx=event.clientX-d.x;if(!d.dragged&&Math.abs(dx)<6)return;d.dragged=true;d.track.classList.add('dragging');d.track.scrollLeft=d.left-dx});
function endGalleryDrag(){if(!dragGallery)return;let {track,left,x}=dragGallery;track.classList.remove('dragging');let index=Math.round(track.scrollLeft/track.clientWidth);track.scrollTo({left:index*track.clientWidth,behavior:'smooth'});dragGallery=null}
document.addEventListener('pointerup',endGalleryDrag);document.addEventListener('pointercancel',endGalleryDrag);
function immersive(){document.querySelector('.phone').classList.add('immersive')}
function timeline(list){return `<div class="timeline">${list.map(m=>`<article><div class="sub">${m.date.replaceAll('-','.')} · ${esc(m.place)}</div><h3><button style="padding:0;text-align:left" onclick="detail(${m.id})">${esc(m.title)}</button></h3><div class="timeline-emotions">${moodBadge(m.mood,m.mood)} ${tagBadge(m.tag)}</div>${m.images.length?gallery(m,'time-gallery'):''}<p>${esc(m.text)}</p></article>`).join('')}</div>`}
function timeDetail(tag){document.querySelector('.phone').classList.add('subpage');$('#nav').style.display='none';let list=memories.filter(m=>m.tag===tag);let title=tag==='山野之间'?'在山野里，找回自己':tag==='出走日记'?'去远方，也回到自己':'平凡日子的闪光';app.innerHTML=coverHero(list.find(m=>m.images.length)?.images[0]||imgs[2],title,`${list.length} 个瞬间 · ${timePeople(tag).join("、")}`,ib('image',`changeCover('${tag}')`,'设置封面')+ib('share',`shareTime('${tag}')`,'分享时光到圈子'))+`<div class="ai"><b>${icon('sparkles')} YOU 的时光手记</b><p>从这些记录里，看见你把时间留给了喜欢的事。走过的路、遇见的人，都在平凡的日子里留下了温柔的回声。</p><button onclick="aiChat()" class="secondary">和 YOU 聊聊这段时光 ${icon('arrow')}</button></div>`+timeline(list);app.scrollTop=0}
function companions(){app.innerHTML=header()+`<div class="banner companion-banner">${icon('people')}<div><b>相遇的意义，是一起记得</b><p>用一个同行码，收藏大家的视角</p></div><button class="round-add icon" aria-label="创建或加入同行" onclick="tripOptions()">${icon('plus')}</button></div><div class="section-label"><b>我的同行</b><span>${trips.length} 段共同经历</span></div>${trips.map((t,i)=>`<div class="feature" role="button" tabindex="0" onclick="tripDetail(${i})" onkeydown="if(event.key==='Enter')this.click()"><img src="${t.image}" alt="${esc(t.name)}"><div class="feature-text"><span class="pill">${t.status}</span><h2>${esc(t.name)}</h2><span>${t.people} 人同行 · ${memories.filter(m=>m.trip===t.name).length} 个瞬间 ${icon('arrow')}</span></div></div>`).join('')}`}
const circleAvatars={};
function circleImage(c,i){return circleAvatars[c]||imgs[(i??circles.indexOf(c))*2%6]||imgs[0]}
function circlePage(){let list=memories.filter(m=>m.scope.includes(selectedCircle));app.innerHTML=header()+`<div class="stories"><button class="story" onclick="circleOptions()"><div class="ring">${icon('plus')}</div>新的圈子</button>${circles.map((c,i)=>`<div class="story-wrap ${c===selectedCircle?'selected':''}"><button class="story ${c===selectedCircle?'selected':''}" onclick="selectCircle(${i})"><div class="ring"><img src="${circleImage(c,i)}" alt="${esc(c)}"></div>${esc(c)}</button>${c===selectedCircle?`<button class="circle-more" aria-label="圈子详情" onclick="circleManage()">${icon('more')}</button>`:''}</div>`).join('')}</div>${list.map(m=>post(m,'我')).join('')}${circles.length?communityExamples.filter(m=>m.scope.includes(selectedCircle)).map(m=>post(m,m.author)).join(''):'<div class="empty">创建或加入圈子，和在意的人分享生活。</div>'}`}
function selectCircle(i){selectedCircle=circles[i];circlePage()}
function circleManage(){sheet(`<div class="circle-profile"><button class="circle-avatar-edit" onclick="changeCircleAvatar()" aria-label="更换圈子头像"><img src="${circleImage(selectedCircle)}" alt="${esc(selectedCircle)}"><span>${icon('image')}</span></button><h2>${esc(selectedCircle)}</h2><p class="sub">属于我们的小天地 · 3 位成员</p><button class="secondary" onclick="changeCircleAvatar()">更换头像</button></div><div class="section-label"><b>圈子成员</b><span>3 人</span></div><div class="member-list">${['我','小满','阿远'].map((name,i)=>`<div><img class="avatar" src="${i===2?photo('photo-1500648767791-00dcc994a43e',100):avatar}" alt="${name}"><span>${name}</span>${i===0?'<small>创建者</small>':''}</div>`).join('')}</div><button class="option" onclick="toast('圈子邀请码：YOU')">邀请朋友 · 查看邀请码 ${icon('share')}</button><button class="option" onclick="confirmLeave()">退出圈子</button>`)}
function changeCircleAvatar(){let c=selectedCircle;pickFiles(files=>{let r=new FileReader();r.onload=()=>{circleAvatars[c]=r.result;circlePage();circleManage();toast('圈子头像已更换')};r.readAsDataURL(files[0])})}

app.addEventListener('scroll',()=>document.querySelector('.phone').classList.toggle('scrolled',app.scrollTop>55));
const peoplePhotos={'我':avatar,'小满':photo('photo-1524504388940-b1c1722653e1',100),'阿远':photo('photo-1500648767791-00dcc994a43e',100),'阿禾':photo('photo-1506794778202-cad84cf45f1d',100)};
function personFace(name,cls='avatar'){return `<img class="${cls}" src="${peoplePhotos[name]||avatar}" alt="${esc(name)}" title="${esc(name)}">`}
function participantFaces(people){return `<div class="participants"><span>一起的人</span><div class="face-stack">${people.split(/[、,，]/).filter(Boolean).map(n=>personFace(n.trim())).join('')}</div></div>`}
function coverHero(src,title,subtitle,extra=''){immersive();return `<section class="cover-hero"><img id="cover" src="${src}" alt="${esc(title)}">${backbar(title,extra)}<div class="cover-title"><span>${subtitle}</span><h1>${esc(title)}</h1></div></section>`}
const communityExamples=[{id:100,title:'今天的风，刚刚好',text:'把忙碌留在城市，把今天留在这里。下次一起。',images:[imgs[5],imgs[0],imgs[2]],date:'2026-10-26',place:'湖边',author:'小满'},{id:101,title:'收集秋天的颜色',text:'沿着小路走了很久，拍下这些舍不得错过的光。',images:[imgs[1],imgs[4],imgs[2],imgs[5]],date:'2026-10-25',place:'九溪',author:'阿远'},{id:102,title:'我们的周末放映室',text:'从山野到湖边，镜头里的每一帧都很喜欢。',images:[imgs[2],imgs[3],imgs[0]],date:'2026-10-24',place:'杭州',author:'阿禾'}];
const seedComments={100:[['阿远','这个光线太美了，下次一起！'],['小满','好呀，等一个晴天。']],101:[['阿禾','第二张好像电影画面。']],102:[['小满','把普通的日子过成了喜欢的样子。']]};
function post(m,author){let likers=m.id%2?['小满','阿禾']:['阿远','小满'];if(likes[m.id])likers=['我',...likers];return `<article class="post" id="post-${m.id}"><div class="post-head">${personFace(author)}<div><b>${esc(author)}</b><small>${m.date.slice(5).replace('-','.')} · ${esc(m.place)}</small></div></div><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p>${m.images.length?gallery(m,'community-gallery'):''}<div class="actions"><button class="${likes[m.id]?'liked':''}" aria-label="${likes[m.id]?'取消喜欢':'喜欢'}" onclick="togglePostLike(${m.id},this)">${icon('heart')} ${likes[m.id]?'已喜欢':'喜欢'}</button><button onclick="commentSheet(${m.id})">${icon('comment')} 评论 ${(seedComments[m.id]?.length||0)+(comments[m.id]?.length||0)}</button><span class="sub" style="margin-left:auto">${esc(selectedCircle)}可见</span></div><div class="liker-row"><div class="face-stack">${likers.map(n=>personFace(n)).join('')}</div><span>${likers.map(esc).join('、')} 喜欢了</span></div><div class="comment-thread">${(seedComments[m.id]||[]).map(([n,s])=>`<div class="comment-line">${personFace(n)}<div><b>${n}</b><span>${esc(s)}</span></div></div>`).join('')}${(comments[m.id]||[]).map(s=>`<div class="comment-line">${personFace('我')}<div><b>我</b><span>${esc(s)}</span></div></div>`).join('')}</div></article>`}
function togglePostLike(id,button){likes[id]=!likes[id];let m=memories.find(m=>m.id===id)||communityExamples.find(m=>m.id===id);let holder=document.createElement('div');holder.innerHTML=post(m,m.author||'我');$('#post-'+id).replaceWith(holder.firstElementChild)}
function customField(key,label,value){return `<div class="custom-field"><span>${label}</span><button type="button" class="field-select" aria-label="${label}" aria-haspopup="dialog" onclick="openField('${key}')"><span>${esc(value)}</span>${icon('back').replace('<svg ','<svg class="chevron-down" ')}</button></div>`}
function editor(){document.querySelector('.phone').classList.add('subpage');document.querySelector('.phone').classList.remove('immersive');closeSheet();$('#nav').style.display='none';draft.tag??='日常碎片';draft.mood??='开心';draft.date??='2026-11-01';draft.scope??=[];app.innerHTML=`<div class="backbar">${ib('back','cancelEdit()','取消编辑')}<b>${draft.id?'编辑瞬间':'新的瞬间'}</b><button class="primary" style="padding:7px 18px;min-height:36px" onclick="publish()">${draft.id?'保存':'发布'}</button></div><div class="form editor-form"><div class="preview-images">${(draft.images||[]).map(src=>`<img src="${src}" alt="待发布照片">`).join('')}<button class="secondary" aria-label="添加照片" onclick="captureDraft();pickForDraft()">${icon('plus')}</button></div><label>标题<input id="title" class="title-input" maxlength="60" value="${esc(draft.title||'')}" placeholder="给这个瞬间起个名字"></label><label>记录此刻<textarea id="body" placeholder="今天，有什么想记住的？">${esc(draft.text||'')}</textarea></label>${customField('tag','标签',draft.tag)}${customField('mood','此刻心情',draft.mood)}${customField('date','记忆时间',draft.date)}<label>地点<input id="place" value="${esc(draft.place||'')}" placeholder="你在哪里"></label><label>一起的人<input id="people" value="${esc(draft.people||'')}" placeholder="用顿号分隔参与者"></label>${customField('trip','关联同行',draft.trip||'不关联同行')}${customField('scope','可见范围',draft.scope.length?draft.scope.join('、'):'私人 · 仅自己可见')}<p class="sub">${icon('lock')} 你的记录，由你决定谁能看见。</p></div>`;app.scrollTop=0}
function captureDraft(){draft={...draft,title:$('#title').value,text:$('#body').value,place:$('#place').value,people:$('#people').value}}
let editorScroll=0,fieldOptions=[],pendingScope=[];
function openField(key){captureDraft();editorScroll=app.scrollTop;if(key==='date'){openCalendar();return}if(key==='scope'){pendingScope=[...draft.scope];scopeMenu();return}fieldOptions=key==='tag'?['日常碎片','出走日记','山野之间']:key==='mood'?Object.keys(moodStyles):['',...trips.map(t=>t.name)];let title={tag:'选择标签',mood:'选择此刻心情',trip:'关联同行'}[key];sheet(`<h2>${title}</h2><div class="choice-list" role="listbox" aria-label="${title}">${fieldOptions.map((value,i)=>`<button class="choice-option ${draft[key]===value?'chosen':''}" role="option" aria-selected="${draft[key]===value}" onclick="chooseField('${key}',${i})"><span>${key==='mood'?moodBadge(value):esc(value||'不关联同行')}</span><i class="choice-mark">${draft[key]===value?'✓':''}</i></button>`).join('')}</div>`)}
function chooseField(key,i){draft[key]=fieldOptions[i];returnEditor()}
function returnEditor(){editor();app.scrollTop=editorScroll}
function scopeMenu(){sheet(`<h2>谁可以看见</h2><p class="sub">私人或多个圈子；同行关联单独设置。</p><div class="choice-list" role="listbox" aria-label="可见范围" aria-multiselectable="true"><button class="choice-option ${!pendingScope.length?'chosen':''}" role="option" aria-selected="${!pendingScope.length}" onclick="pendingScope=[];scopeMenu()"><span>${icon('lock')} 私人 · 仅自己可见</span><i class="choice-mark">${!pendingScope.length?'✓':''}</i></button>${circles.map((c,i)=>`<button class="choice-option ${pendingScope.includes(c)?'chosen':''}" role="option" aria-selected="${pendingScope.includes(c)}" onclick="toggleScope(${i})"><span>${icon('people')} ${esc(c)}</span><i class="choice-mark">${pendingScope.includes(c)?'✓':''}</i></button>`).join('')}</div><button class="primary full" onclick="draft.scope=[...pendingScope];returnEditor()">确认范围</button>`)}
function toggleScope(i){let c=circles[i];pendingScope=pendingScope.includes(c)?pendingScope.filter(n=>n!==c):[...pendingScope,c];scopeMenu()}
let calendarYear=2026,calendarMonth=10;
function openCalendar(){let [y,m]=draft.date.split('-').map(Number);calendarYear=y;calendarMonth=m-1;calendarMenu()}
function calendarMenu(){let first=new Date(calendarYear,calendarMonth,1).getDay(),days=new Date(calendarYear,calendarMonth+1,0).getDate();sheet(`<h2>记忆时间</h2><div class="calendar-title">${ib('back','moveMonth(-1)','上个月')}<b>${calendarYear} 年 ${calendarMonth+1} 月</b>${ib('arrow','moveMonth(1)','下个月')}</div><div class="calendar-grid">${['日','一','二','三','四','五','六'].map(d=>`<span>${d}</span>`).join('')}${Array(first).fill('<span></span>').join('')}${Array.from({length:days},(_,i)=>{let d=i+1,date=`${calendarYear}-${String(calendarMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return `<button class="${date===draft.date?'chosen':''}" aria-label="${date}" onclick="draft.date='${date}';returnEditor()">${d}</button>`}).join('')}</div>`)}
function moveMonth(offset){calendarMonth+=offset;if(calendarMonth<0){calendarMonth=11;calendarYear--}if(calendarMonth>11){calendarMonth=0;calendarYear++}calendarMenu()}

document.querySelector('.status').insertAdjacentHTML('afterend',brandHeader());
function header(){return ''}

// Review rules: identity, source membership and participant sets are distinct.
let momentTab='Yours';
const circleMembers={'三两好友':['我','小满','阿远'],'我的家人':['我','妈妈','爸爸'],'周末徒步社':['我','小满','阿远','阿禾']};
communityExamples.forEach((m,i)=>Object.assign(m,{tag:i===1?'山野之间':'日常碎片',mood:'开心',people:i===2?'阿禾':'小满',scope:i===2?['周末徒步社']:['三两好友'],trip:i===0?'周末逃离计划':''}));
const isMine=m=>!m.author||m.author==='我';
const related=m=>m.scope?.some(c=>circles.includes(c))||trips.some(t=>t.name===m.trip);
function allMoments(){return [...new Map([...memories,...communityExamples.filter(related)].map(m=>[m.id,m])).values()]}
function switchMomentTab(t){momentTab=t;moments()}
function moments(){app.innerHTML=header()+`<div class="moment-tools"><div class="moment-topbar"><div class="moment-tabs" role="tablist" aria-label="瞬间范围">${[['Yours','你'],['Related','与你有关']].map(([t,label])=>`<button role="tab" aria-selected="${momentTab===t}" class="${momentTab===t?'active':''}" onclick="switchMomentTab('${t}')">${label}</button>`).join('')}</div></div></div><div class="section-label"><b id="result-label"></b><span id="result-count" aria-live="polite"></span></div><div id="grid"></div>`;updateGrid()}
function updateGrid(){let searching=!!query.trim();let list=allMoments().filter(m=>(searching?true:momentTab==='Yours'?isMine(m):related(m))&&[m.title,m.text,m.place,m.people,m.author].join(' ').toLowerCase().includes(query.trim().toLowerCase()));$('#result-label').textContent=searching?'搜索你和与你有关的瞬间':momentTab==='Yours'?'自己发布的所有瞬间':'相关同行与圈子中的瞬间';$('#result-count').textContent=`${list.length} 个瞬间`;$('#grid').innerHTML=list.length?`<div class="masonry">${[0,1].map(c=>`<div class="column">${list.filter((_,i)=>i%2===c).map(m=>card(m)+`<p class="source-caption">${esc(m.author||'我')} · ${esc([m.trip,...(m.scope||[])].filter(Boolean).join(' / ')||'仅自己可见')}</p>`).join('')}</div>`).join('')}</div>`:'<div class="empty">暂无符合条件的瞬间</div>'}
function sourceLinks(m){return `${trips.some(t=>t.name===m.trip)?`<button class="secondary" onclick="openSourceTrip(${trips.findIndex(t=>t.name===m.trip)})">同行 · ${esc(m.trip)} ${icon('arrow')}</button>`:''}${(m.scope||[]).filter(c=>circles.includes(c)).map(c=>`<button class="secondary" onclick="openSourceCircle(${circles.indexOf(c)})">圈子 · ${esc(c)} ${icon('arrow')}</button>`).join('')}`}
function openSourceTrip(i){if(!trips[i])return toast('同行已不可访问');go('同行');tripDetail(i)}
function openSourceCircle(i){if(!circles[i])return toast('圈子已不可访问');selectedCircle=circles[i];go('圈子')}
function shareMemory(id){let m=memories.find(m=>m.id===id);if(!m)return toast('只有作者可以分享');sheet(`<h2>分享瞬间</h2><p class="sub">选择同行与圈子。清空圈子不会取消同行分享。</p><label>同行<select id="share-trip"><option value="">不分享到同行</option>${trips.map((t,i)=>`<option value="${i}" ${m.trip===t.name?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><h3>圈子</h3>${circles.map((c,i)=>`<label class="row">${esc(c)}<input type="checkbox" name="share" value="${i}" ${m.scope.includes(c)?'checked':''}></label>`).join('')}<button class="primary full" onclick="commitMomentShare(${id})">保存分享</button>`)}
function commitMomentShare(id){let m=memories.find(m=>m.id===id);if(!m)return toast('瞬间不存在');let t=$('#share-trip').value;m.trip=t===''?'':trips[Number(t)]?.name||'';m.scope=[...document.querySelectorAll('[name=share]:checked')].map(e=>circles[Number(e.value)]).filter(Boolean);save();closeSheet();detail(id);toast('同行与圈子分享已更新')}
function timePeople(tag){return [...new Set(memories.filter(m=>m.tag===tag).flatMap(m=>['我',...(m.people||'').split(/[、,，]/).map(n=>n.trim()).filter(Boolean)]))]}
function canShareTime(tag,c){let members=circleMembers[c]||['我'];return circles.includes(c)&&timePeople(tag).every(n=>members.includes(n))}
let timeShares;try{timeShares=JSON.parse(localStorage.getItem('you-time-shares'))||{}}catch{timeShares={}}
function shareTime(tag){let people=timePeople(tag);sheet(`<h2>分享时光到圈子</h2><p class="sub">时光涉及 ${people.map(esc).join('、')}。所有涉及用户均为圈子成员时可分享，成员相等也允许。</p>${circles.map((c,i)=>{let ok=canShareTime(tag,c),missing=people.filter(n=>!(circleMembers[c]||['我']).includes(n));return `<label class="row ${ok?'':'unavailable'}"><span>${esc(c)}<small class="sub" style="display:block">${ok?'满足成员条件':`无法分享：${missing.map(esc).join('、')}不在圈内`}</small></span><input type="checkbox" name="time-share" value="${i}" ${ok?'':'disabled'} ${ok&&(timeShares[tag]||[]).includes(c)?'checked':''}></label>`}).join('')}<p class="sub">分享入口不扩大原瞬间权限，接收者仍按原权限查看。</p><button class="primary full" onclick="commitTimeShare('${tag}')">保存分享</button>`)}
function commitTimeShare(tag){let chosen=[...document.querySelectorAll('[name=time-share]:checked')].map(e=>circles[Number(e.value)]);if(!chosen.every(c=>canShareTime(tag,c)))return toast('成员关系已变化，请重新选择');timeShares[tag]=chosen;try{localStorage.setItem('you-time-shares',JSON.stringify(timeShares))}catch{toast('分享仅保留在本次会话')}closeSheet();toast(chosen.length?'时光分享已更新':'已取消时光圈子分享')}
const renderCircle=circlePage;
circlePage=function(){renderCircle();let shared=Object.keys(timeShares).filter(tag=>timeShares[tag].includes(selectedCircle)&&canShareTime(tag,selectedCircle));app.insertAdjacentHTML('beforeend',shared.map(tag=>`<button class="list-card" onclick="timeDetail('${tag}')"><div><span class="sub">我分享的时光</span><h3>${esc(tag)}</h3><p>查看时光 ${icon('arrow')}</p></div></button>`).join(''))};
go('瞬间');
